CREATE TABLE IF NOT EXISTS "panda_realty"."lead_imports" (
  "lead_import_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "source_email" citext NOT NULL,
  "advertisement_id" citext NOT NULL,
  "entity_id" bigint,
  "property_entity_id" bigint,
  "raw_email_text" text,
  "created_at" timestamp DEFAULT now(),
  CONSTRAINT "lead_imports_source_email_advertisement_id_key" UNIQUE ("source_email", "advertisement_id")
);
